function allDebris(f){return f.detached.flatMap(child=>[child,...allDebris(child)]);}
function vesselCenter(f){return statistics(f.parts,f.fuel,f.ballast).com.applyQuaternion(f.q).add(f.pos);}
function updateDebrisVisuals(){for(const f of allDebris(flight)){let group=debrisVisuals.get(f);if(!group){group=new T.Group();for(const p of f.parts){const o=makePartVisual(p);if(PARTS[p.type].thrust&&!PARTS[p.type].water){const flame=new T.Mesh(new T.ConeGeometry(.23,1.3,16),new T.MeshBasicMaterial({color:'#ffba60',transparent:true,opacity:.8,depthWrite:false}));flame.rotation.z=Math.PI;flame.position.y=-PARTS[p.type].size[1]/2-.5;const target=o.userData.gimbal||o;if(o.userData.gimbal)flame.position.y-=PARTS[p.type].gimbalPivot[1];target.add(flame);o.userData.debrisFlame=flame;}group.add(o);}testWorld.add(group);debrisVisuals.set(f,group);group.userData.canopies=new Map();for(const p of f.parts)if(PARTS[p.type].parachute){const canopy=cloneModel('parachute-open');testWorld.add(canopy);group.userData.canopies.set(p.id,canopy);}}for(const [id,canopy]of group.userData.canopies){const state=f.chutes.get(id),p=f.parts.find(p=>p.id===id);canopy.visible=!!p&&!!state&&state.fraction>0;if(canopy.visible){canopy.position.fromArray(p.p).applyQuaternion(f.q).add(f.pos);canopy.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),localUp(canopy.position));const scale=Math.sqrt(state.fraction);canopy.scale.set(scale,.45+.55*scale,scale);}}group.position.copy(f.pos);group.quaternion.copy(f.q);for(const o of group.children){const id=o.userData.partId;updateRCSVisual(o,f);if(o.userData.debrisFlame){o.userData.debrisFlame.visible=(f.engineThrust.get(id)||0)>1&&!f.crashed;o.userData.debrisFlame.scale.y=.5+f.throttle;}if(o.userData.hinge)o.userData.hinge.rotation.x=f.deflections.get(id)||0;if(o.userData.gimbal){const g=f.gimbals.get(id);o.userData.gimbal.rotation.set(g?.x||0,0,g?.z||0);}if(o.userData.rollingVisual){const wheel=f.wheelMotion.get(id);o.userData.steeringVisual.rotation.y=wheel?.steer||0;o.userData.rollingVisual.rotation.x=wheel?.angle||0;}}}}
function updateDebrisList(){const children=allDebris(flight),list=$('#debrisList');list.replaceChildren();$('#debrisCount').textContent=children.length;for(const [index,f]of children.entries()){const row=document.createElement('div'),text=document.createElement('small'),button=document.createElement('button');text.textContent='機体 '+(index+1)+' · '+f.parts.length+'部品 · '+((f.orbit?.altitude||0)/1000).toFixed(1)+' km · '+f.vel.length().toFixed(0)+' m/s · 燃料 '+Math.round(f.fuelRatio*100)+'% · 電力 '+powerTotals(f.parts,f.charge).stored.toFixed(0)+' EC'+(f.crashed?' · 損傷':f.landed?' · 着地':'');button.textContent=trackedDebris===f?'追跡中':'追跡';button.onclick=()=>{trackedDebris=f;const target=vesselCenter(f);controls.target.copy(target);camera.position.copy(target).add(new T.Vector3(14,10,18));flightFocus.copy(target);updateDebrisList();};const take=document.createElement('button');take.textContent=canControl(f)?'操縦':'制御不可';take.disabled=!canControl(f);take.onclick=()=>switchVessel(f);const targetButton=document.createElement('button');targetButton.textContent=flight.navigationTarget===f?'目標指定中':'目標にする';targetButton.onclick=()=>{setTarget(flight,flight,f);updateNavigation();updateDebrisList();};row.append(text,button,take,targetButton);list.append(row);}}
$('#trackPrimary').onclick=()=>{trackedDebris=null;frame();};
function flightCenter(){return statistics(flight.parts,flight.fuel,flight.ballast).com.applyQuaternion(flight.q).add(flight.pos);}
function frame(){const bounds=new T.Box3().setFromObject(craftRoot);if(bounds.isEmpty())return;const center=flight?flightCenter():bounds.getCenter(new T.Vector3());if(flight)flightFocus.copy(center);const size=bounds.getSize(new T.Vector3()).length();controls.target.copy(center);camera.position.copy(center).add(new T.Vector3(1,.65,1.3).normalize().multiplyScalar(Math.max(7,size*1.35)));controls.update();}
function craftData(){return {version:1,name:$('#craftName').value,parts:structuredClone(parts)};}
function loadData(data){const loaded=validateCraft(data);checkpoint();parts=loaded;$('#craftName').value=typeof data.name==='string'?data.name.slice(0,80):'Untitled';cancelPlacement();rebuild();frame();}
function showModal(html){$('#modalBody').innerHTML=html;$('#modal').showModal();}$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
const newButton=document.createElement('button');newButton.className='wide';newButton.textContent='＋ 新規機体';$('#examples').after(newButton);newButton.onclick=()=>{if(flight)return;checkpoint();parts=[];selected=null;cancelPlacement();$('#craftName').value='Untitled / 01';rebuild();notify('部品を選び、床面をクリックして最初の部品を置けます');};
const examples={rendezvous:['Rendezvous / 12','相対航法試験機','Spaceを2回で分離 · 相手を目標指定 · RCSで接近','orbit'],rcs:['Attitude Lab / 11','RCS試験機','ホイール無効 · RでRCS · IJKLUOで並進','orbit'],twin:['Gemini / 10','双子探査機','Spaceを2回で分離 · 他機体へ操縦切替','orbit'],recovery:['Recovery / 09','カプセル降下試験','高度1 km · パラシュートをHで待機','drop'],returner:['Pioneer Return / 08','帰還ロケット','2段式 · 分離カプセル · パラシュート','land'],launcher:['Pioneer Heavy / 07','軌道投入ロケット','2段式 · 下段4基 · 上段1基','land'],rocket:['Pioneer / 01','ロケット','45 kN · 4枚フィン','land'],orbiter:['Surveyor / 02','宇宙探査機','無人コア · ソーラーパネル','land'],plane:['Swift / 03','ジェット機','独立操舵面 · 前輪1＋主脚2','runway'],rover:['Nomad / 04','ローバー','4輪駆動 · 無人探査','land'],boat:['Tern / 05','双胴艇','フロート · スクリュー','water'],sub:['Nautilus / 06','潜水艇','注排水タンク · 水中推進','water']};
$('#examples').onclick=()=>{if(flight)return;showModal('<div class="eyebrow">START FROM A BLUEPRINT</div><h2>最初の一機を選ぶ</h2><p>見本機を改造して、設計を試せます。現在の機体は「元に戻す」で復元できます。</p><div class="examplegrid">'+Object.entries(examples).map(([k,v])=>`<button data-example="${k}"><b>${v[1]}</b><span>${v[0]}<br>${v[2]}</span></button>`).join('')+'</div>');$$('[data-example]').forEach(b=>b.onclick=()=>{const k=b.dataset.example;checkpoint();parts=preset(k);$('#craftName').value=examples[k][0];setBay(['plane','boat','sub','rover'].includes(k)?'sph':'vab');$('#environment').value=examples[k][3];selected=null;cancelPlacement();rebuild();frame();$('#modal').close();});};
$('#help').onclick=()=>showModal('<div class="eyebrow">WORKSHOP FIELD GUIDE</div><h2>設計から試験まで</h2><p>左の部品を選び、機体の取付位置をクリック。接続点・表面・自由配置を切り替え、対称配置で翼やブースターを取り付けられます。</p><div class="helpgrid"><b>右ドラッグ / ホイール</b><span>視点回転 / 拡大縮小</span><b>中ドラッグ</b><span>平行移動</span><b>G / R / Esc</b><span>移動 / 回転 / 配置取消・選択モード</span><b>F / Delete</b><span>機体全体を表示 / 選択した接続枝を削除</span><b>Ctrl+Z / Ctrl+Y</b><span>元に戻す / やり直す</span><b>試験 → Space</b><span>点火 / 次のステージ実行</span><b>Shift / Ctrl / X</b><span>推力を上げる / 下げる / 停止</span><b>W/S · A/D · Q/E</b><span>ピッチ · ヨー · ロール</span><b>T / ピッチトリム</b><span>SAS姿勢保持 / 舵の中立を調整</span><b>車輪 / 操作ON・OFF</b><span>始動後W/Sで前後進、A/Dで操向。下部のチェックで姿勢制御・車輪操舵・駆動を個別に切替。両方ONならW/Sは姿勢と駆動の両方へ作用。</span><b>バラスト</b><span>海面試験で注排水。増やすと重くなる</span></div><p>ジェット見本は全開で約30秒加速後、Sを約2秒押して機首上げ。舵は気流によって効き、低速では姿勢を変えにくくなります。黄色は重心、水色は水平・機首+Zでの空力中心近似。吹き下ろしなどの干渉は未計算です。</p><p>保存はこのブラウザ内。JSON出力で機体を持ち出せます。現版は局所的な試験場です。球形惑星・軌道・再突入熱・電力消費・破断応力は未実装。Δvは共通タンクと平均比推力からの参考値です。</p>');
function setBay(b){if(flight)return;bayMode=b;$('#vab').classList.toggle('active',b==='vab');$('#sph').classList.toggle('active',b==='sph');$('#bayno').textContent=b==='vab'?'01':'02';if(b==='sph')$('#environment').value='runway';showNodes();updateInfo();}
$('#aero').onclick=()=>{aeroMarker.visible=!aeroMarker.visible;$('#aero').classList.toggle('active',aeroMarker.visible);};
$('#trim').oninput=e=>{if(flight)flight.trim=+e.target.value/100;$('#trimVal').textContent=e.target.value+'%';};
$('#vab').onclick=()=>setBay('vab');$('#sph').onclick=()=>setBay('sph');$('#frame').onclick=frame;$('#com').onclick=()=>{comMarker.visible=!comMarker.visible;$('#com').classList.toggle('active',comMarker.visible);};$('#undo').onclick=undo;$('#redo').onclick=redo;$$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$('#attach').onchange=showNodes;$('#snap').onchange=()=>{gizmo.setTranslationSnap($('#snap').checked?.25:null);gizmo.setRotationSnap($('#snap').checked?Math.PI/12:null);};$('#snap').onchange();$('#environment').onchange=updateInfo;
$('#save').onclick=()=>{try{localStorage.setItem('orbital-foundry-craft',JSON.stringify(craftData()));notify('このブラウザに機体を保存しました');}catch{notify('保存できませんでした。JSON出力を使ってください。');}};$('#load').onclick=()=>{if(flight)return;try{const s=localStorage.getItem('orbital-foundry-craft');if(!s){notify('保存された機体がありません');return;}loadData(JSON.parse(s));notify('保存した機体を読み込みました');}catch(e){notify(e.message);}};$('#export').onclick=()=>{const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(craftData(),null,2)],{type:'application/json'}));a.href=url;a.download=($('#craftName').value.replace(/[^\p{L}\p{N}_-]/gu,'_')||'craft')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);};$('#import').onclick=()=>{if(!flight)$('#file').click();};$('#file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('機体ファイルが大きすぎます');loadData(JSON.parse(await file.text()));notify('機体を読み込みました');}catch(e){notify(e.message);}$('#file').value='';};
function disposeWorld(){testWorld.traverse(o=>{if(o.userData.sharedAsset)return;o.geometry?.dispose();if(o.material){const mats=Array.isArray(o.material)?o.material:[o.material];mats.forEach(m=>m.dispose());}});testWorld.clear();}
let surfacePatch;
function buildTestWorld(environment){disposeWorld();const color=environment==='water'?'#164c64':'#627569';const globe=new T.Mesh(new T.SphereGeometry(PLANET.radius,256,128),mat(color,.05,.95));globe.position.copy(center);testWorld.add(globe);const geometry=new T.PlaneGeometry(4000,4000,64,64);geometry.rotateX(-Math.PI/2);const positions=geometry.attributes.position;for(let i=0;i<positions.count;i++){const x=positions.getX(i),z=positions.getZ(i);positions.setY(i,Math.sqrt(PLANET.radius**2-x*x-z*z)-PLANET.radius+.01);}geometry.computeVertexNormals();surfacePatch=new T.Mesh(geometry,mat(color,.05,.95));surfacePatch.receiveShadow=true;testWorld.add(surfacePatch);if(environment!=='water'){const runwayGeometry=new T.PlaneGeometry(18,1600,1,80);runwayGeometry.rotateX(-Math.PI/2);runwayGeometry.translate(0,0,650);const rp=runwayGeometry.attributes.position;for(let i=0;i<rp.count;i++)rp.setY(i,.025-(rp.getX(i)**2+rp.getZ(i)**2)/(2*PLANET.radius));runwayGeometry.computeVertexNormals();const runway=new T.Mesh(runwayGeometry,mat('#3a4245'));runway.receiveShadow=true;testWorld.add(runway);for(let z=-40;z<1400;z+=22)box(testWorld,[.25,.01,8],[0,.035-z*z/(2*PLANET.radius),z],mat('#d8d7bd'));}}
$('#clearTarget').onclick=()=>{if(flight){setTarget(flight,flight,null);updateNavigation();updateDebrisList();}};
function updateNavigation(){resolveTargets(flight);const relative=relativeState(flight,flight.navigationTarget);$('#targetInfo').textContent=relative?'目標まで '+relative.distance.toFixed(1)+' m · 相対速度 '+relative.speed.toFixed(2)+' m/s':'目標未指定';$('#targetDetail').textContent=relative?(relative.closing>=0?'接近 ':'離脱 ')+Math.abs(relative.closing).toFixed(2)+' m/s · '+(relative.braking?'減速方向まで '+(Math.acos(T.MathUtils.clamp(new T.Vector3(0,flight.rocketAxes?1:0,flight.rocketAxes?0:1).applyQuaternion(flight.q).dot(relative.braking),-1,1))*180/Math.PI).toFixed(0)+'° · 整列後 I でRCS噴射':'速度差 0.01 m/s以下 · 噴射を停止'):'';$('#clearTarget').hidden=!relative;const nav=drawNavball($('#navball'),flight.q,flight.rocketAxes,flightCenter(),flight.vel);$('#navPitch').textContent='PITCH '+nav.pitch.toFixed(0)+'° · ＋順行 / ×逆行';$('#sasMode').value=flight.sasMode;}
function updateOrbit(){const o=flight.orbit||orbitState(flight.pos,flight.vel),km=x=>Number.isFinite(x)?(x/1000).toFixed(1)+' km':'∞';$('#orbitInfo').textContent=(o.stable?'周回軌道':o.energy>=0?'脱出軌道':o.periapsis<0?'地表と交差':'大気と交差')+' · 遠点 '+km(o.apoapsis)+' · 近点 '+km(o.periapsis);$('#maneuverHud').textContent=flight.maneuver?(flight.maneuver.complete?'予定Δv到達 · Xで停止':'計画残り '+new T.Vector3(...flight.maneuver.remaining).length().toFixed(1)+' m/s · '+(flight.maneuver.time>=flight.time?'噴射まで ':'予定から ')+formatDuration(Math.abs(flight.maneuver.time-flight.time))):'';$('#orbitDetail').textContent='円軌道速度 '+o.circularSpeed.toFixed(0)+' m/s · 重力 '+o.gravity.toFixed(2)+' m/s²';drawOrbit($('#orbitMap'),o);if(!$('#orbitOverlay').hidden)updateOrbitPlan(o);const up=localUp(flight.pos);surfacePatch.position.copy(up).multiplyScalar(PLANET.radius).add(center);surfacePatch.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),up);scene.background.set('#02050d').lerp(new T.Color('#8eb5c8'),Math.max(0,1-o.altitude/70000));scene.fog=null;}

function toggleOrbitMap(){if(!flight)return;$('#orbitOverlay').hidden=!$('#orbitOverlay').hidden;if(!$('#orbitOverlay').hidden)updateOrbit();}
$('#openOrbitMap').onclick=toggleOrbitMap;$('#closeOrbitMap').onclick=()=>$('#orbitOverlay').hidden=true;
for(const id of ['planEnabled','planLocation','planDeltaV'])$('#'+id).addEventListener('input',()=>{if(flight)updateOrbit();});
$('#fixManeuver').onclick=()=>{if(!flight)return;try{const value=$('#planDeltaV').value;if(value.trim()==='')throw Error('予定Δvを入力してください');const preview=maneuverPreview(flightCenter(),flight.vel,$('#planLocation').value,Number(value));flight.maneuver=createManeuverNode(preview,flight.time);$('#planEnabled').checked=false;updateOrbit();notify('噴射計画を固定しました。点火・停止は手動です。');}catch(e){notify(e.message);}};
$('#alignManeuver').onclick=()=>{if(!flight?.maneuver)return;launchPilot=null;flight.sas=true;flight.sasMode='maneuver';$('#sas').textContent='SAS ON';$('#sas').classList.add('active');};
$('#clearManeuver').onclick=()=>{if(!flight)return;flight.maneuver=null;if(flight.sasMode==='maneuver'){flight.sasMode='hold';flight.holdQ=flight.q.clone();}updateOrbit();};
$('#mapCutoff').onclick=()=>{if(flight){launchPilot=null;flight.throttle=0;$('#throttle').value=0;updateOrbit();}};
function updateOrbitPlan(o){const plan=apsisPlan(o);let preview=null;$('#maneuverResult').textContent='比較プレビューはOFFです。';if($('#planEnabled').checked){try{const value=$('#planDeltaV').value;if(value.trim()==='')throw new Error('予定Δvを入力してください');preview=maneuverPreview(flightCenter(),flight.vel,$('#planLocation').value,Number(value));const km=x=>Number.isFinite(x)?(x/1000).toFixed(1)+' km':'なし（脱出）';$('#maneuverResult').textContent='予定地点まで '+formatDuration(preview.time)+' · Δv '+preview.deltaV.toFixed(1)+' m/s\n予測遠点 '+km(preview.orbit.apoapsis)+' / 近点 '+km(preview.orbit.periapsis)+(preview.orbit.periapsis<0?'\n予測軌道は地表と交差します':preview.orbit.periapsis<PLANET.atmosphereTop?'\n予測軌道は大気と交差します':'');}catch(error){$('#maneuverResult').textContent=error.message;}}const node=flight.maneuver;$('#alignManeuver').disabled=!node;$('#clearManeuver').disabled=!node;$('#fixedManeuverStatus').textContent='計画なし';if(node){const remaining=new T.Vector3(...node.remaining).length(),dt=node.time-flight.time,forward=new T.Vector3(0,flight.rocketAxes?1:0,flight.rocketAxes?0:1).applyQuaternion(flight.q),angle=forward.angleTo(maneuverDirection(node))*180/Math.PI;$('#fixedManeuverStatus').textContent=(node.complete?'目標Δv到達：スロットルを切ってください':dt>=0?'噴射まで '+formatDuration(dt):'予定時刻から '+formatDuration(-dt))+'\n残り '+remaining.toFixed(1)+' m/s · 方向差 '+angle.toFixed(1)+'°';if(!preview)preview={orbit:orbitState(new T.Vector3(...node.position),new T.Vector3(...node.velocity))};}drawOrbit($('#largeOrbitMap'),o,{detail:true,preview});$('#mapFlightState').textContent='現在 '+o.speed.toFixed(1)+' m/s · スロットル '+Math.round(flight.throttle*100)+'%';$('#orbitKind').textContent={circular:'ほぼ円軌道',ellipse:'楕円軌道',escape:'脱出軌道',radial:'半径方向の飛行'}[plan.kind];$('#orbitCaution').textContent=plan.caution;$('#orbitPeriod').textContent='公転周期 '+formatDuration(plan.period);for(const key of ['apoapsis','periapsis']){const point=plan[key],name=key==='apoapsis'?'遠点':'近点';$('#'+key+'Plan').textContent=point?name+' '+(point.altitude/1000).toFixed(1)+' km\n到達まで '+formatDuration(point.time)+'\n円軌道化：'+(point.deltaV===null?'地表内のため不可':(point.deltaV>=0?'順行 ':'逆行 ')+Math.abs(point.deltaV).toFixed(1)+' m/s'):name+'：'+(plan.kind==='circular'?'円軌道では方向が定まりません':'なし');}$('#orbitPlanNote').textContent=plan.kind==='escape'?'遠点はありません。近点の到達時間「—」は通過済み、または計算対象外です。':plan.kind==='circular'?'遠点・近点を指定する必要がない、ほぼ円形の軌道です。':'Δvはその遠点・近点で瞬間的に噴射する場合の目安です。現在位置での噴射量ではありません。';}

const exhaust=[];function startFlight(restored=null){if(!parts.length){notify('まず機体を組み立ててください');return;}if(!parts.some(p=>PARTS[p.type].control)){notify('試験には制御ユニットが必要です');return;}if(parts.filter(p=>!p.parent).length!==1){notify('独立した部品を接続してから試験してください');return;}cancelPlacement();gizmo.detach();highlight.visible=false;comMarker.visible=false;aeroMarker.visible=false;flight=restored instanceof Flight?restored:new Flight(parts,$('#environment').value);launchPilot=null;$('#autoLaunch').textContent='自動軌道投入（見本用）';$('#autoLaunch').hidden=!parts.some(p=>PARTS[p.type].decoupler)||flight.environment==='orbit'||!flight.rocketAxes;accumulated=0;trackedDebris=null;debrisVisuals.clear();buildTestWorld(flight.environment);parachuteVisuals.clear();chuteFramed=false;for(const p of flight.parts)if(PARTS[p.type].parachute){const canopy=cloneModel('parachute-open');canopy.visible=false;testWorld.add(canopy);parachuteVisuals.set(p.id,canopy);}$('#armChutes').hidden=!parachuteVisuals.size;$('#autoReturn').hidden=!parachuteVisuals.size||!flight.parts.some(p=>PARTS[p.type].decoupler)||!flight.parts.some(p=>PARTS[p.type].thrust);testWorld.visible=true;bay.visible=false;scene.background=new T.Color('#8eb5c8');scene.fog=new T.Fog('#9fbdc5',300,2000);document.body.classList.add('flying');$('#flightHud').hidden=false;$('#launch').disabled=true;$('#throttle').value=0;$('#ballast').value=0;$('#trim').value=0;$('#trimVal').textContent='0%';for(const [key,available] of [['rcsEnabled',parts.some(p=>PARTS[p.type].rcsThrust)],['reactionEnabled',parts.some(p=>PARTS[p.type].reactionTorque)],['steeringEnabled',parts.some(p=>PARTS[p.type].steer)],['driveEnabled',parts.some(p=>p.type==='wheel')]]){const el=$('#'+key);el.checked=flight[key];el.parentElement.hidden=!available;}$('#ballastControl').hidden=!parts.some(p=>PARTS[p.type].ballast);$('#sas').classList.add('active');$('#sas').textContent='SAS ON';$('#brake').classList.add('active');$('#brake').textContent='BRAKE ON';controls.maxDistance=2000000;$('#warp').value='1';for(const p of parts){if(PARTS[p.type].thrust&&!PARTS[p.type].water){const flame=new T.Mesh(new T.ConeGeometry(.23,1.3,16),new T.MeshBasicMaterial({color:PARTS[p.type].air?'#76cdff':'#ffba60',transparent:true,opacity:.8,depthWrite:false}));flame.rotation.z=Math.PI;flame.position.y=-PARTS[p.type].size[1]/2-.5;flame.visible=false;const target=objects.get(p.id).userData.gimbal||objects.get(p.id);if(PARTS[p.type].gimbal)flame.position.y-=PARTS[p.type].gimbalPivot[1];target.add(flame);exhaust.push({id:p.id,mesh:flame});}}craftRoot.position.copy(flight.pos);craftRoot.quaternion.copy(flight.q);frame();notify(flight.environment==='orbit'?'高度80 kmの初期円軌道から開始。無推力で周回します。':'Spaceで始動。車輪はW/Sで前後進、A/Dで操向。');}
