$('#quickSave').onclick=quickSave;$('#quickLoad').onclick=quickLoad;$('#resumeFlight').onclick=quickLoad;
$('#launch').onclick=()=>startFlight();$('#back').onclick=endFlight;$('#stage').onclick=stage;$('#throttle').oninput=e=>{launchPilot=null;$('#autoLaunch').textContent='自動軌道投入（見本用）';if(flight)flight.throttle=+e.target.value/100;};$('#ballast').oninput=e=>{if(flight)flight.ballast=+e.target.value/100;};$('#sas').onclick=()=>{if(!flight)return;flight.sas=!flight.sas;$('#sas').classList.toggle('active',flight.sas);$('#sas').textContent='SAS '+(flight.sas?'ON':'OFF');};$('#brake').onclick=()=>{if(!flight)return;flight.brake=!flight.brake;$('#brake').classList.toggle('active',flight.brake);$('#brake').textContent='BRAKE '+(flight.brake?'ON':'OFF');};
window.addEventListener('keydown',e=>{if(flight&&['F5','F9'].includes(e.code)){e.preventDefault();if(!e.repeat)(e.code==='F5'?quickSave:quickLoad)();return;}if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||$('#modal').open)return;if(flight&&e.code==='KeyM'){if(!e.repeat)toggleOrbitMap();return;}if(e.code==='Escape'&&!$('#orbitOverlay').hidden){$('#orbitOverlay').hidden=true;return;}keys.add(e.code);if(['Space','Delete','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.repeat)return;if(flight){if(e.code==='KeyR')$('#rcsEnabled').click();if(e.code==='KeyH')flight.armParachutes();if(e.code==='Space')stage();if(e.code==='KeyB')$('#brake').click();if(e.code==='KeyT')$('#sas').click();if(e.code==='KeyX'){flight.throttle=0;$('#throttle').value=0;}return;}if(e.ctrlKey&&e.code==='KeyZ'){e.preventDefault();undo();}else if(e.ctrlKey&&e.code==='KeyY'){e.preventDefault();redo();}else if(e.code==='Escape'){cancelPlacement();setMode('select');}else if(e.code==='KeyG')setMode('translate');else if(e.code==='KeyR')setMode('rotate');else if(e.code==='KeyF')frame();else if(e.code==='Delete')deleteSelected();});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
